pipe_integration.code_snippet:
async fn execute_pending_action(&mut self, pending: &PendingAction) -> Result<()> {
    let parts: Vec<&str> = pending.action.split_whitespace().collect();
    match match_command(parts[0]) {
        Some("ts") => { self.set_trailing_stop(&parts[1..], Some(pending.side)).await?; }
    }
}

payload_handler.code_snippet:
ClientPayload::SetTrailingStop(req) => {
    match self.bybit.set_trailing_stop(&req.symbol, req.side, req.trailing_stop, req.active_price).await {
        Ok(_) => ServerMessage::new(ServerPayload::TrailingStopSet { symbol: req.symbol }),
        Err(e) => ServerMessage::new(ServerPayload::Error { code: 1, message: e.to_string() }),
    }
}

